from collections import deque
from typing import List

class Solution:
    def shortestDistanceAfterQueries(self, n: int, queries: List[List[int]]) -> List[int]:
        # Initialize the graph with initial roads: i -> i+1 for all i from 0 to n-2
        graph = [[] for _ in range(n)]
        for i in range(n - 1):
            graph[i].append(i + 1)

        result = []

        for u, v in queries:
            # Add the new road from u to v
            graph[u].append(v)

            # Find shortest path from 0 to n-1 using BFS
            dist = [-1] * n
            dist[0] = 0
            queue = deque([0])

            while queue:
                city = queue.popleft()
                if city == n - 1:
                    break

                for neighbor in graph[city]:
                    if dist[neighbor] == -1:
                        dist[neighbor] = dist[city] + 1
                        queue.append(neighbor)

            result.append(dist[n - 1])

        return result

class Solution:
    def finalPositionOfSnake(self, n: int, commands: List[str]) -> int:
        # Start at position 0 (top-left corner)
        row, col = 0, 0

        # Process each command
        for command in commands:
            if command == "RIGHT":
                col += 1
            elif command == "LEFT":
                col -= 1
            elif command == "DOWN":
                row += 1
            elif command == "UP":
                row -= 1

        # Convert final row and column back to position
        return row * n + col

class Solution:
    def countOfPairs(self, nums: List[int]) -> int:
        MOD = 10**9 + 7
        n = len(nums)

        # dp[i][j] = number of ways to assign arr1[0] to arr1[i] such that arr1[i] = j
        max_val = max(nums)
        dp = [[0] * (max_val + 1) for _ in range(n)]

        # Base case: position 0
        for val in range(nums[0] + 1):
            dp[0][val] = 1

        # Fill the DP table
        for i in range(1, n):
            for curr_val in range(nums[i] + 1):
                # Try all possible previous values
                for prev_val in range(nums[i-1] + 1):
                    # Check if we can transition from prev_val to curr_val
                    # arr1 must be non-decreasing: prev_val <= curr_val
                    # arr2 must be non-increasing: (nums[i-1] - prev_val) >= (nums[i] - curr_val)
                    # This simplifies to: curr_val - prev_val >= nums[i-1] - nums[i]

                    if prev_val <= curr_val and curr_val - prev_val >= nums[i-1] - nums[i]:
                        dp[i][curr_val] = (dp[i][curr_val] + dp[i-1][prev_val]) % MOD

        # Sum all possibilities for the last position
        result = 0
        for val in range(nums[n-1] + 1):
            result = (result + dp[n-1][val]) % MOD

        return result

